INSERT INTO `events` VALUES (9,'Multaqo Sanawi','<p>Hadirilah</p>','04/10/2023 - 04/10/2023','2023-10-04','2023-10-04','Multaqo-sanawi-7','PP. Darussa\'adah','image/event/QBUaR8AR8ZnLf50L28P8hh9Its6mejR7EvwlHZgK.png','1',NULL,'2023-10-17 00:15:13','Rp. 100.000'),(10,'Multaqo Sanawi 7','<p>KABAR GEMBIRA&nbsp;</p>\r\n\r\n<p>HADIRILAH!!!<br />\r\nMULTAQO SANAWI 7&nbsp;<br />\r\nPertemuan Internasional Alumni Pondok Pesantren DARUSSAADAH AL ISLAMY li Sayyidil Walid Abuya Nur Hasanuddin Bin Abdul Latief&nbsp;</p>\r\n\r\n<p>Yang insyaallah akan di laksanakan pada :<br />\r\nHari : Sabtu &amp; Ahad<br />\r\nTgl : 04-05 November 2023</p>\r\n\r\n<p>Untuk pembayaran :&nbsp;<br />\r\nInfaq / iuran via transfer Bank BRI : 6380-01-030461-53-1<br />\r\nA.n Achmad Rifa&#39;i</p>\r\n\r\n<p>Konfirmasi :&nbsp;<br />\r\nBendahara 087780002888 Achmad Rifa&#39;i</p>\r\n\r\n<p>Mari jangan menunggu waktu luang tapi kita luangkan waktu dan kita prioritas kan wafa&rsquo; kita kepada guru kita&nbsp;</p>\r\n\r\n<p>الله يوفقكم و يبارك فيكم&nbsp;<br />\r\nSemoga kita mendapatkan keberkahan daripada guru semua , Amieeennn</p>\r\n\r\n<p>SHARE&nbsp;SERENTAK</p>','04/11/2023 - 05/11/2023','2023-11-05','2023-11-04','MultaqoSanawi7','Masjid Darussa\'adah Kampus 3','image/event/4XZt4V8dkhJH6i2f1jmTJXCoqrS9gSaIgiOp2Bar.jpg','1',NULL,'2023-10-17 00:15:28','Rp. 100.000');
/*!40000 ALTER TABLE `events` ENABLE KEYS */;
UNLOCK TABLES;

